// 為每個字串建立排序後的 key，再依 key 排序索引，相同 key 連續出現即為同一組
// 時間複雜度: O(n · k log k + n log n · k)，空間複雜度: O(n · k)
static char** keys;

static int cmpChar(const void* a, const void* b) {
    return *(const char*)a - *(const char*)b;
}

static int cmpIdx(const void* a, const void* b) {
    return strcmp(keys[*(const int*)a], keys[*(const int*)b]);
}

char*** groupAnagrams(char** strs, int strsSize, int* returnSize, int** returnColumnSizes) {
    keys = malloc(sizeof(char*) * strsSize);
    int* order = malloc(sizeof(int) * strsSize);
    for (int i = 0; i < strsSize; i++) {
        keys[i] = strdup(strs[i]);
        qsort(keys[i], strlen(keys[i]), 1, cmpChar);
        order[i] = i;
    }
    qsort(order, strsSize, sizeof(int), cmpIdx);

    char*** result = malloc(sizeof(char**) * strsSize);
    *returnColumnSizes = malloc(sizeof(int) * strsSize);
    *returnSize = 0;

    for (int i = 0; i < strsSize; ) {
        int j = i;
        while (j < strsSize && strcmp(keys[order[i]], keys[order[j]]) == 0) j++;
        char** group = malloc(sizeof(char*) * (j - i));
        for (int t = i; t < j; t++) group[t - i] = strs[order[t]];
        (*returnColumnSizes)[*returnSize] = j - i;
        result[(*returnSize)++] = group;
        i = j;
    }

    for (int i = 0; i < strsSize; i++) free(keys[i]);
    free(keys);
    free(order);
    return result;
}
